		const docSnapshot = TextDocumentSnapshot.create(document);
		const language = getLanguage(docSnapshot);
		if (!wholeRange) {
			wholeRange = selection;
		}
		return {
			document: docSnapshot, fileIndentInfo: undefined, language, selection, wholeRange
		};
