import { PromptElementProps, PromptSnapshotNode } from '../../../../prompt/src/components/components';

/**
 * A component that marks the context part of the prompt
 */
export function CompletionsContext(props: PromptElementProps) {
	return props.children;
}

/**
 * A component that marks the context part of the prompt that is stable across requests,
 * and should be located earlier in the prompt to maximize cache hits.
 */
export function StableCompletionsContext(props: PromptElementProps) {
	return props.children;
}

/**
 * A component that marks the context part of the prompt that is subject to change quickly across requests,
 * and should be located further down in the prompt.
 */
export function AdditionalCompletionsContext(props: PromptElementProps) {
	return props.children;
}

export function isContextNode(node: PromptSnapshotNode): boolean {
	return (
		node.name === CompletionsContext.name ||
		node.name === StableCompletionsContext.name ||
		node.name === AdditionalCompletionsContext.name
	);
}

/**
 * Excerpt generator component for the excerpt panel.
 */

/**
 * WordPress dependencies
 */
import { Button, Notice } from '@wordpress/components';
import { update } from '@wordpress/icons';
import { __ } from '@wordpress/i18n';
import { Stack } from '@wordpress/ui';

/**
 * Internal dependencies
 */
import { useExcerptGeneration } from './useExcerptGeneration';

const { aiExcerptGenerationData } = window as any;

/**
 * ExcerptGeneration component.
 *
 * Provides a button to generate an excerpt.
 *
 * @return {React.JSX.Element | null} The excerpt generation component.
 */
export default function ExcerptGeneration(): React.JSX.Element | null {
	const {
		isGenerating,
		hasExcerpt,
		isContentTooShort,
		tooShortLabel,
		handleGenerate,
	} = useExcerptGeneration();

	// Don't render if disabled.
	if ( ! aiExcerptGenerationData?.enabled ) {
		return null;
	}

	let buttonLabel: string = __( 'Generate excerpt', 'ai' );

	if ( isGenerating ) {
		buttonLabel = __( 'Generating…', 'ai' );
	} else if ( hasExcerpt ) {
		buttonLabel = __( 'Regenerate excerpt', 'ai' );
	}

	return (
		<Stack direction="column" gap="md">
			{ isContentTooShort && (
				<Notice status="warning" isDismissible={ false }>
					{ tooShortLabel }
				</Notice>
			) }

			<Button
				icon={ update }
				variant="secondary"
				label={ isContentTooShort ? tooShortLabel : buttonLabel }
				onClick={ handleGenerate }
				disabled={ isGenerating || isContentTooShort }
				accessibleWhenDisabled
				isBusy={ isGenerating }
				__next40pxDefaultSize
				style={ { alignSelf: 'flex-start' } }
			>
				{ buttonLabel }
			</Button>
		</Stack>
	);
}

